command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FLEDERMAUSLEIB (Prozentualer Live-Sync)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Fledermausleib";
    const ahne = "brona"; 
    const finalEffektName = `${gabenName} (Brona)`;
    const iconBild = DSK_FW.Symbol(ahne);

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER & TOKEN ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    let casterToken = casterActor.getActiveTokens()[0] || canvas.tokens.controlled[0];
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Ich brauche deinen Token auf der Karte für die Verwandlung!");

    const qs = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => ownerIds.add(id));

    // --- 3. BERECHNUNGEN ---
    const dauerMinuten = qs * 5;
    const dauerSekunden = dauerMinuten * 60;
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';
    const dauerCalc = `<span ${thinStyle}>(${qs} QS x 5)</span>`;

    // --- 4. VERWANDLUNG: TOKEN AUSTAUSCHEN (Mit Prozent-Sync) ---
    await casterToken.document.update({ hidden: true });

    let batActor = game.actors.getName("Fledermaus");
    if (!batActor) {
        batActor = await fromUuid("Actor.DEINE_NEUE_UUID_HIER_FALLS_NÖTIG"); 
    }

    if (!batActor) {
        ui.notifications.warn("Luna sagt 🌙: Konnte die Fledermaus nicht finden! Hast du sie in die Welt importiert?");
    } else {
        let td = await batActor.getTokenDocument();
        let tokenData = td.toObject();
        tokenData.x = casterToken.x;
        tokenData.y = casterToken.y;
        tokenData.hidden = false;
        tokenData.actorLink = false; 

        // Prozentuale Berechnung für den Start der Fledermaus
        const cLeP = casterActor.system.stats.LeP;
        const cAeP = casterActor.system.stats.AeP;
        const bMaxLeP = batActor.system.stats.LeP.max || 1;
        const bMaxAeP = batActor.system.stats.AeP.max || 1;

        const pctLeP = Math.max(0, Math.min(1, cLeP.value / (cLeP.max || 1)));
        const pctAeP = Math.max(0, Math.min(1, cAeP.value / (cAeP.max || 1)));

        tokenData.delta = {
            system: {
                stats: {
                    LeP: { value: Math.max(1, Math.round(bMaxLeP * pctLeP)) },
                    AeP: { value: Math.round(bMaxAeP * pctAeP) }
                }
            }
        };

        foundry.utils.setProperty(tokenData, "flags.dsk.isFledermausVon", casterActor.uuid);
        await canvas.scene.createEmbeddedDocuments("Token", [tokenData]);
    }

    // --- 5. EFFEKT ANWENDEN ---
    let alterEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        description: `Der Leib der Vampirkatze zerfällt in Fledermäuse. Eine davon bist du. (Keine weiteren Ahnengaben wirkbar). Deine LeP & AeP sind prozentual mit der Fledermaus verknüpft!`,
        duration: { seconds: dauerSekunden },
        changes: [{
            key: "flags.dsk.status",
            mode: 2,
            value: "Verwandelt in Fledermaus",
            priority: 20
        }],
        flags: {
            core: { statusId: "fledermausleib" },
            dsk: { ahne: ahne, casterUuid: casterActor.uuid, hiddenTokenId: casterToken.id }
        }
    }]);

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("fledermausleib", finalEffektName, "Die Fledermaus verwandelt sich zurück. LeP und AeP bleiben prozentual aktuell.");
    }

    // --- 6. PROZENTUALER LIVE-SYNC & CLEANUP REGISTRIEREN (Blutband) ---
    if (!globalThis._dskFledermausSystem) {
        globalThis._dskFledermausSystem = true;

        Hooks.on("updateActor", async (updatedActor, changes, options, userId) => {
            if (!game.user.isGM) return; 
            if (options.dskFledermausSync) return; // Verhindert Endlosschleife!

            const lepChange = foundry.utils.getProperty(changes, "system.stats.LeP.value");
            const aepChange = foundry.utils.getProperty(changes, "system.stats.AeP.value");
            if (lepChange === undefined && aepChange === undefined) return;

            if (updatedActor.isToken) { // Fledermaus ändert sich -> Caster prozentual anpassen
                const casterUuid = updatedActor.token.getFlag("dsk", "isFledermausVon");
                if (casterUuid) {
                    const caster = await fromUuid(casterUuid);
                    if (caster) {
                        let finalUpdate = {};
                        if (lepChange !== undefined) {
                            const batMax = updatedActor.system.stats.LeP.max || 1;
                            const pct = Math.max(0, Math.min(1, lepChange / batMax));
                            finalUpdate["system.stats.LeP.value"] = Math.round((caster.system.stats.LeP.max || 1) * pct);
                        }
                        if (aepChange !== undefined) {
                            const batMax = updatedActor.system.stats.AeP.max || 1;
                            const pct = Math.max(0, Math.min(1, aepChange / batMax));
                            finalUpdate["system.stats.AeP.value"] = Math.round((caster.system.stats.AeP.max || 1) * pct);
                        }
                        if (Object.keys(finalUpdate).length > 0) await caster.update(finalUpdate, { dskFledermausSync: true });
                    }
                }
            } else { // Caster ändert sich -> Fledermaus prozentual anpassen
                const bats = canvas.scene ? canvas.scene.tokens.filter(t => t.getFlag("dsk", "isFledermausVon") === updatedActor.uuid) : [];
                for (let bat of bats) {
                    if (bat.actor) {
                        let finalUpdate = {};
                        if (lepChange !== undefined) {
                            const casterMax = updatedActor.system.stats.LeP.max || 1;
                            const pct = Math.max(0, Math.min(1, lepChange / casterMax));
                            finalUpdate["system.stats.LeP.value"] = Math.max(1, Math.round((bat.actor.system.stats.LeP.max || 1) * pct));
                        }
                        if (aepChange !== undefined) {
                            const casterMax = updatedActor.system.stats.AeP.max || 1;
                            const pct = Math.max(0, Math.min(1, aepChange / casterMax));
                            finalUpdate["system.stats.AeP.value"] = Math.round((bat.actor.system.stats.AeP.max || 1) * pct);
                        }
                        if (Object.keys(finalUpdate).length > 0) await bat.actor.update(finalUpdate, { dskFledermausSync: true });
                    }
                }
            }
        });

        Hooks.on("deleteActiveEffect", async (effect) => {
            if (!game.user.isGM) return; 
            if ((effect.name || effect.label) === finalEffektName) {
                const actorUuid = effect.parent?.uuid;
                if (!actorUuid) return;

                const bats = canvas.scene.tokens.filter(t => t.getFlag("dsk", "isFledermausVon") === actorUuid);

                if (bats.length > 0) {
                    const batActor = bats[0].actor;
                    if (batActor && effect.parent) {
                        let finalUpdate = {};
                        const batLeVal = batActor.system.stats.LeP.value;
                        if (batLeVal !== undefined) {
                            const batMax = batActor.system.stats.LeP.max || 1;
                            const pct = Math.max(0, Math.min(1, batLeVal / batMax));
                            finalUpdate["system.stats.LeP.value"] = Math.round((effect.parent.system.stats.LeP.max || 1) * pct);
                        }
                        const batAeVal = batActor.system.stats.AeP.value;
                        if (batAeVal !== undefined) {
                            const batMax = batActor.system.stats.AeP.max || 1;
                            const pct = Math.max(0, Math.min(1, batAeVal / batMax));
                            finalUpdate["system.stats.AeP.value"] = Math.round((effect.parent.system.stats.AeP.max || 1) * pct);
                        }
                        if (Object.keys(finalUpdate).length > 0) await effect.parent.update(finalUpdate, { dskFledermausSync: true });
                    }
                }

                const hiddenId = effect.getFlag("dsk", "hiddenTokenId");
                if (hiddenId) {
                    const origToken = canvas.scene.tokens.get(hiddenId);
                    if (origToken) await origToken.update({ hidden: false });
                }

                if (bats.length > 0) await canvas.scene.deleteEmbeddedDocuments("Token", bats.map(t => t.id));
            }
        });
    }

    // --- 7. FLAG-CLEANUP ---
    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    // --- 8. CHAT-KARTE BAUEN ---
    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom: 8px;"><b>${casterActor.name}</b> wirkt Fledermausleib.</p>
                <p style="margin-top:0; text-align: left;">Der Leib der Vampirkatze zerfällt in Fledermäuse, die davonfliegen. Eine dieser Fledermäuse bist du.</p>
                <ul class="dsklist" style="margin-bottom: 8px; text-align: left;">
                    <li><b style="color: #18940F;">Live-Verbindung:</b> Die Fledermaus teilt sich ab sofort ihre Lebens- und Astralpunkte <b style="text-decoration:underline;">prozentual</b> in Echtzeit mit dir!</li>
                    <li><b style="color: #B30000;">Einschränkung:</b> Es können keine weiteren Ahnengaben gewirkt werden.</li>
                </ul>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold; margin-bottom: 0;">
                    Wirkungsdauer:<br>${dauerMinuten} Minuten ${dauerCalc}
                </p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent, whisper: Array.from(ownerIds) });
    } else {
        await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
            content: cardContent
        });
    }
})();
